expand_details.cypher:
MATCH (start:namespace {name: 'obs'})
CALL apoc.path.expandConfig(start, {
    sequence: 'namespace,encapsulates,pod,hosts,node',
    minLevel: 0,
    maxLevel: 2,
    bfs: true
})
YIELD path
RETURN path, length(path) AS hops
ORDER BY hops;

